import os
import re
import hashlib
import hmac
import time
from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import subprocess
from urllib.parse import urlparse, parse_qs
import threading

# ML Inference Server with RBAC
SECRET_KEY = os.environ.get('SERVER_SECRET', 'default-dev-key-change-in-prod')
MODEL_REGISTRY = {}
AUDIT_LOG_DIR = '/var/log/ml_server/'
TEMPLATE_DIR = '/opt/ml_server/templates/'

class RolePermissions:
    ROLES = {
        'admin': ['inference', 'model_manage', 'audit', 'report'],
        'data_scientist': ['inference', 'model_manage', 'report'],
        'analyst': ['inference', 'report'],
        'viewer': ['report']
    }

    @staticmethod
    def check_permission(role, action):
        return action in RolePermissions.ROLES.get(role, [])


class SessionStore:
    _sessions = {}
    _lock = threading.Lock()

    @classmethod
    def create_session(cls, user_id, role):
        token = hmac.new(SECRET_KEY.encode(), f"{user_id}:{time.time()}".encode(), hashlib.sha256).hexdigest()
        with cls._lock:
            cls._sessions[token] = {'user_id': user_id, 'role': role, 'created': time.time()}
        return token

    @classmethod
    def get_session(cls, token):
        with cls._lock:
            session = cls._sessions.get(token)
            if session and (time.time() - session['created']) < 3600:
                return session
            elif session:
                del cls._sessions[token]
        return None


class ReportRenderer:
    """Renders server-side report templates with model metrics."""

    ALLOWED_DIRECTIVES = {'echo', 'printenv', 'config'}

    def __init__(self, template_base=TEMPLATE_DIR):
        self.template_base = template_base
        self._cache = {}

    def _sanitize_template_name(self, name):
        # Prevent path traversal
        basename = os.path.basename(name)
        if not basename.endswith('.shtml'):
            basename += '.shtml'
        return basename

    def _resolve_includes(self, content, depth=0):
        """Process SSI-like include directives for report composition."""
        if depth > 5:
            return content
        # Process <!--#include virtual="..." --> directives
        include_pattern = re.compile(r'<!--#include\s+virtual="([^"]+)"\s*-->')
        def replace_include(match):
            inc_path = match.group(1)
            resolved = self._safe_resolve(inc_path)
            if resolved:
                return self._resolve_includes(resolved, depth + 1)
            return '<!-- include not found -->'
        return include_pattern.sub(replace_include, content)

    def _safe_resolve(self, path):
        """Resolve include path safely within template directory."""
        full_path = os.path.normpath(os.path.join(self.template_base, path))
        if not full_path.startswith(self.template_base):
            return None
        try:
            with open(full_path, 'r') as f:
                return f.read()
        except (IOError, OSError):
            return None

    def _process_directives(self, content, context):
        """Process SSI directives in template content."""
        # Process <!--#echo var="..." --> directives
        echo_pattern = re.compile(r'<!--#echo\s+var="([^"]+)"\s*-->')
        def replace_echo(match):
            var_name = match.group(1)
            return str(context.get(var_name, f'(undefined:{var_name})'))
        content = echo_pattern.sub(replace_echo, content)

        # Process <!--#exec cmd="..." --> for admin report generation
        exec_pattern = re.compile(r'<!--#exec\s+cmd="([^"]+)"\s*-->')
        def replace_exec(match):
            cmd = match.group(1)
            return self._execute_report_command(cmd, context)
        content = exec_pattern.sub(replace_exec, content)

        return content

    def _execute_report_command(self, cmd, context):
        """Execute report generation commands. Only allowed for admin context."""
        # Validate the command is a known report tool
        allowed_commands = ['generate_metrics', 'model_summary', 'system_status']
        cmd_base = cmd.split()[0] if cmd.split() else ''
        if cmd_base not in allowed_commands:
            return '<!-- command not allowed -->'
        try:
            result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=10)
            return result.stdout
        except subprocess.TimeoutExpired:
            return '<!-- command timeout -->'
        except Exception:
            return '<!-- command error -->'

    def render_report(self, template_name, context, user_role):
        """Render a report template with the given context."""
        safe_name = self._sanitize_template_name(template_name)
        template_path = os.path.join(self.template_base, safe_name)

        try:
            with open(template_path, 'r') as f:
                content = f.read()
        except (IOError, OSError):
            return None

        # First resolve includes
        content = self._resolve_includes(content)

        # Then process directives with context
        # Context includes user-supplied model names for report headers
        content = self._process_directives(content, context)

        return content


class MLInferenceHandler(BaseHTTPRequestHandler):
    renderer = ReportRenderer()

    def _authenticate(self):
        auth_header = self.headers.get('Authorization', '')
        if auth_header.startswith('Bearer '):
            token = auth_header[7:]
            return SessionStore.get_session(token)
        return None

    def do_POST(self):
        session = self._authenticate()
        if not session:
            self.send_error(401, 'Unauthorized')
            return

        path = urlparse(self.path).path
        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length).decode('utf-8')

        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self.send_error(400, 'Invalid JSON')
            return

        if path == '/api/report/generate':
            self._handle_report(session, data)
        elif path == '/api/inference':
            self._handle_inference(session, data)
        else:
            self.send_error(404)

    def _handle_report(self, session, data):
        if not RolePermissions.check_permission(session['role'], 'report'):
            self.send_error(403, 'Forbidden')
            return

        template = data.get('template', 'default_report')
        model_name = data.get('model_name', 'unknown')
        report_title = data.get('title', 'ML Model Report')

        # Build context for template rendering
        context = {
            'MODEL_NAME': model_name,
            'REPORT_TITLE': report_title,
            'GENERATED_AT': time.strftime('%Y-%m-%d %H:%M:%S'),
            'USER': session['user_id'],
            'ROLE': session['role']
        }

        result = self.renderer.render_report(template, context, session['role'])
        if result is None:
            self.send_error(404, 'Template not found')
            return

        self.send_response(200)
        self.send_header('Content-Type', 'text/html')
        self.end_headers()
        self.wfile.write(result.encode('utf-8'))

    def _handle_inference(self, session, data):
        if not RolePermissions.check_permission(session['role'], 'inference'):
            self.send_error(403, 'Forbidden')
            return
        # Inference logic placeholder
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({'prediction': 0.95}).encode())


def run_server(port=8443):
    server = HTTPServer(('127.0.0.1', port), MLInferenceHandler)
    print(f"ML Inference Server running on port {port}")
    server.serve_forever()


if __name__ == '__main__':
    os.makedirs(AUDIT_LOG_DIR, exist_ok=True)
    run_server()
